"""Pydantic Models for Agent Decisions and Guardrail Validations."""
from typing import List, Optional, Dict, Any
from pydantic import BaseModel, Field

class DispatchDecision(BaseModel):
    """Structured output generated by the CrewAI Dispatch Agent."""
    order_id: str
    assigned_driver_id: str
    assigned_driver_name: str
    rationale: str
    evaluated_drivers_count: int
    predicted_delay_mins: float
    confidence_score: float = Field(ge=0.0, le=1.0, default=0.95)

class RoutePlan(BaseModel):
    """Structured output generated by the Google ADK Route Agent."""
    order_id: str
    driver_id: str
    selected_route: str
    distance_km: float
    estimated_eta_mins: float
    mcp_tool_calls_used: int = 1
    alternative_count: int = 2

class ExceptionReplan(BaseModel):
    """Structured output generated by the CrewAI Exception Agent upon mid-route disruptions."""
    order_id: str
    original_driver_id: str
    disruption_cause: str  # "TRAFFIC_ACCIDENT", "HOURS_LIMIT_REACHED", "ROAD_BLOCKAGE"
    recovery_action: str   # "REASSIGN_DRIVER", "REROUTE_CURRENT_DRIVER", "SPLIT_CONSIGNMENT"
    reassigned_driver_id: str
    new_route: str
    new_eta_mins: float
    time_saved_mins: float
    rationale: str

class GuardrailEvaluation(BaseModel):
    """Validation report returned by the Multi-Tier Safety Guardrail Layer."""
    passed: bool
    violations: List[str] = Field(default_factory=list)
    action_taken: str  # "ALLOW", "BLOCK", "MASK_AND_PROCEED", "FLAG_FOR_REVIEW"
    interventions: int = 0
